import{_ as a}from"./chunks/analytics_spotify.Vl1ZPEQh.js";import{_ as n}from"./chunks/analytics_episode_explorer.BWRHWryF.js";import{_ as r,H as i,c as l,b as c,a0 as t,K as s}from"./chunks/framework.DZ_FiXNr.js";const b=JSON.parse(`{"title":"Analytics","description":"Read listening and viewing reports next to your podcast's discovery work. Analytics keeps each source's own measurements visible: host downloads, Spotify plays, Apple listening, and YouTube views describe different things and must not be added into a single audience total.","frontmatter":{},"headers":[],"relativePath":"features/analytics.md","filePath":"features/analytics.md"}`),d={name:"features/analytics.md"};function p(h,e,g,u,m,f){const o=i("HelpWalkthrough");return c(),l("div",null,[e[0]||(e[0]=t('<h1 id="analytics" tabindex="-1">Analytics <a class="header-anchor" href="#analytics" aria-label="Permalink to &quot;Analytics&quot;">​</a></h1><p>Read listening and viewing reports next to your podcast&#39;s discovery work. Analytics keeps each source&#39;s own measurements visible: host downloads, Spotify plays, Apple listening, and YouTube views describe different things and must not be added into a single audience total.</p><p><strong>To access:</strong> choose your podcast, then click <strong>Analytics</strong> in the sidebar. The source bar contains <strong>Spotify · YouTube · Apple Podcasts</strong>, your supported host&#39;s name (such as <strong>Spreaker</strong>, <strong>Buzzsprout</strong>, <strong>Simplecast</strong>, <strong>Captivate</strong>, <strong>Transistor</strong> or <strong>Podigee</strong>), <strong>Tracker</strong> for OP3, <strong>hopr.fm</strong>, and <strong>Overview</strong>, as applicable to your show. PodSEO remembers your selected view, so use the source bar if Analytics opens somewhere different from a guide&#39;s screenshot.</p><p><a href="/images/analytics_spotify.webp" title="Open screenshot at full size"><img src="'+a+'" alt="Spotify analytics with source tabs and local report navigation"></a></p><h2 id="connect-first-then-choose-a-report" tabindex="-1">Connect first, then choose a report <a class="header-anchor" href="#connect-first-then-choose-a-report" aria-label="Permalink to &quot;Connect first, then choose a report&quot;">​</a></h2><p>If a source is not connected, its tab shows the relevant setup steps. Follow <a href="/features/analytics-connections.html">Analytics Connections</a> for Spotify, Apple Podcasts, YouTube, supported hosts, OP3, and hopr.fm. Manage existing accounts from <a href="/features/connections.html">Settings → Connections</a>.</p><p>Connections are available on every plan. YouTube has a limited Free view; organization roles determine who can connect or change access.</p><h2 id="source-by-source-guides" tabindex="-1">Source-by-source guides <a class="header-anchor" href="#source-by-source-guides" aria-label="Permalink to &quot;Source-by-source guides&quot;">​</a></h2><p>Use the dedicated guides for the actual reports and episode details, rather than treating setup as a walkthrough of the whole source:</p><ul><li><a href="/features/spotify-analytics.html">Spotify analytics</a>: discovery, episode reports, listening retention, audience, benchmarks and Partner Program.</li><li><a href="/features/apple-podcasts-analytics.html">Apple Podcasts analytics</a>: plays, followers, episode launches, listening curves and Apple&#39;s reporting windows.</li><li><a href="/features/hosting-analytics.html">Hosting platform analytics</a>: Spreaker/Buzzsprout/Simplecast/Captivate/Transistor/Podigee downloads, episode comparisons and audience reports.</li><li><a href="/features/hopr-fm-analytics.html">hopr.fm analytics</a>: counted/excluded requests, day and reason investigation, launches and download timing.</li><li><a href="/features/op3-analytics.html">OP3 data</a>: the Analytics Tracker source, complete launch windows and unavailable counts.</li><li><a href="/features/youtube-insights.html">YouTube analytics</a>: viewing, discovery, episode/video matches and channel reports.</li></ul><h2 id="navigate-within-a-source" tabindex="-1">Navigate within a source <a class="header-anchor" href="#navigate-within-a-source" aria-label="Permalink to &quot;Navigate within a source&quot;">​</a></h2><p>Connected sources have a second row of views. The exact options depend on what that platform reports:</p><table tabindex="0"><thead><tr><th>View</th><th>What to look for</th></tr></thead><tbody><tr><td><strong>Overview</strong></td><td>Headline metrics and daily trends for this source</td></tr><tr><td><strong>Episodes</strong></td><td>Episode performance, launch comparisons, and available episode details</td></tr><tr><td><strong>Audience</strong></td><td>Geography, demographics, apps, or devices, depending on the source</td></tr><tr><td><strong>Discovery</strong></td><td>How people find the show or channel, including Spotify impressions and YouTube search terms</td></tr><tr><td><strong>Benchmarks</strong>, <strong>Partner Program</strong>, <strong>Podcast playlists</strong>, or <strong>More</strong></td><td>Additional reports when the source provides them</td></tr></tbody></table><p>Source dates matter. A report with no data, a withheld value, or an incomplete day isn&#39;t a zero. Read the reporting window and any coverage or connection warning before comparing periods.</p><h2 id="compare-listening-with-changes-to-your-show" tabindex="-1">Compare listening with changes to your show <a class="header-anchor" href="#compare-listening-with-changes-to-your-show" aria-label="Permalink to &quot;Compare listening with changes to your show&quot;">​</a></h2><p>Choose the <strong>Overview</strong> tab at the end of the source bar, then <strong>Timeline</strong>. It puts each connected source alongside releases, metadata changes, and other recorded events.</p><ul><li><strong>Separate</strong> keeps each source on its own scale.</li><li><strong>Overlay</strong> places the lines together to compare their timing; the numbers are still separate measurements.</li><li>Hover a day to read its values and events.</li><li>Where available, choose <strong>This show</strong> or <strong>Whole channel</strong> for YouTube. A channel with several shows can have more views than the playlist for this podcast.</li></ul>',17)),s(o,{src:"/walkthroughs/analytics-timeline.webp",poster:"/images/analytics_overview.webp",alt:"Switch the Analytics timeline from Separate to Overlay and back",duration:19700}),e[1]||(e[1]=t('<p>To follow the demonstration, open <strong>Overview → Timeline</strong>, switch to <strong>Overlay</strong> to compare timing, then return to <strong>Separate</strong> to read each source on its own scale. This changes the presentation, not the measurements.</p><p>An increase after a title change is a useful lead to investigate, not proof that the change caused it.</p><h2 id="compare-the-same-episode-across-platforms" tabindex="-1">Compare the same episode across platforms <a class="header-anchor" href="#compare-the-same-episode-across-platforms" aria-label="Permalink to &quot;Compare the same episode across platforms&quot;">​</a></h2><p>In the source bar&#39;s <strong>Overview</strong>, choose <strong>Across platforms</strong> to open the <strong>Episode explorer</strong>. Select an episode and compare the measurements available from your connected sources. Keep views, plays, downloads, and listening curves in their own context.</p><p><a href="/images/analytics_episode_explorer.webp" title="Open screenshot at full size"><img src="'+n+'" alt="Episode explorer comparing one episode across connected platforms"></a></p><p>For source-specific episode details, use <strong>Episodes</strong> inside that source. For video matching and title suggestions, use <a href="/features/youtube-insights.html">YouTube analytics</a>.</p><h2 id="compare-listening-curves-and-select-a-passage" tabindex="-1">Compare listening curves and select a passage <a class="header-anchor" href="#compare-listening-curves-and-select-a-passage" aria-label="Permalink to &quot;Compare listening curves and select a passage&quot;">​</a></h2><p>In <strong>Overview → Across platforms</strong>, choose an episode from the list. Use <strong>Find an episode…</strong> to locate another title. The available source badges show where measurements exist; not every episode has every curve. YouTube measurements appear for confirmed full-episode matches.</p><p>The <strong>Listening retention</strong> chart aligns the available Apple and Spotify curves by elapsed time:</p><ul><li><strong>Retained %</strong> sets each source&#39;s own count at 0:00 to 100%, so you can compare the shape of listening.</li><li><strong>Drop from start</strong> shows 100 minus that percentage. It is not a count of people who abandoned the episode.</li><li><strong>Reported counts</strong> shows the source observations. These are not a combined audience.</li></ul><p>Skipping, replaying and different methods affect the curves: values can exceed 100%, drops can be negative, and percentage comparison is unavailable without a valid starting count. Different edits or ads may shift the same passage between platforms.</p><h3 id="zoom-into-the-opening-or-a-selected-interval" tabindex="-1">Zoom into the opening or a selected interval <a class="header-anchor" href="#zoom-into-the-opening-or-a-selected-interval" aria-label="Permalink to &quot;Zoom into the opening or a selected interval&quot;">​</a></h3><ol><li>Click <strong>Focus opening</strong> to zoom into the beginning. <strong>Full episode</strong> restores the full range.</li><li>Choose <strong>Select interval</strong>, enter <strong>From</strong> and <strong>To</strong> as minutes and seconds, then <strong>Apply</strong>. You can also drag horizontally over the main chart.</li><li>Read <strong>Selected interval</strong> for the source values in that passage. <strong>Adjust interval</strong> changes its times; the close button clears it.</li><li>Use the lower navigator to change the visible range. The navigator supports dragging and keyboard controls. <strong>Episode position</strong> explores one point; it is different from selecting an interval.</li></ol>',13)),s(o,{src:"/walkthroughs/episode-interval.webp",poster:"/images/analytics_episode_interval.webp",alt:"Focus the opening, select an interval and compare listening curves for the same episode",duration:37400}),e[2]||(e[2]=t('<p>Chapter buttons, when available, select Spotify&#39;s reported passages; check the note about different edits before comparing with Apple. <strong>Reported values</strong> and <strong>Export CSV</strong> expose the underlying observations.</p><p>Below the curves, each source&#39;s episode card retains its unit, measurement window, read date and available match information. Use <strong>Open … reports</strong> for the complete source detail. <strong>The episode over time</strong> compares available daily plays/downloads using its date control; gaps remain unavailable and counts stay separate.</p><h2 id="common-questions" tabindex="-1">Common questions <a class="header-anchor" href="#common-questions" aria-label="Permalink to &quot;Common questions&quot;">​</a></h2><p><strong>Why don&#39;t my totals match?</strong> Platforms count different actions, cover different audiences, and report at different times. A hosting download is not the same as an Apple listener or a YouTube view.</p><p><strong>Where do I change a connection?</strong> Open <strong>Settings → Connections</strong>, filter by show, and expand the provider. Setup and reporting links return you to the relevant source.</p><p><strong>Where are my search positions?</strong> Use <a href="/features/rankings.html">Search Visibility → Rankings</a> for positions and <a href="/features/keyword-tracker.html">Tracker</a> for their history. Analytics shows the listening and viewing data available from connected platforms.</p><p><strong>Why claim my show on Apple Podcasts or Spotify if my host already publishes it there?</strong> Claiming gives you the platform&#39;s own listener data and promotion tools, and it&#39;s what lets you connect them here. See <a href="/academy/why-you-should-claim-your-podcast-on-apple-and-spotify.html">Why You Should Claim Your Podcast on Apple Podcasts and Spotify</a>.</p>',7))])}const _=r(d,[["render",p]]);export{b as __pageData,_ as default};
